 const page=await browser.newPage();page.setDefaultTimeout(1500);const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const cdp=await page.context().newCDPSession(page);await cdp.send('Profiler.enable');await cdp.send('Profiler.startPreciseCoverage',{callCount:true,detailed:true});
 const row={name};rows.push(row);
 const snapshot=()=>page.evaluate(()=>({route:jtml.getCurrentRoute?.(),state:{loginEmail:jtml.state?.loginEmail,sessionToken:jtml.state?.sessionToken,auditTrail:jtml.state?.auditTrail},headings:[...document.querySelectorAll('h1,h2')].filter(x=>x.getClientRects().length).map(x=>x.textContent),inputs:[...document.querySelectorAll('input')].filter(x=>x.getClientRects().length).map(x=>x.outerHTML),fallbacks:jtml.directComponentBindingDiagnostics,instances:jtml.componentInstances?.map(x=>({component:x.component,id:x.id,role:x.role,parentId:x.parentId,slots:x.slotPlan?.length})),body:document.body.innerText.slice(0,2500)}));
 await page.goto(`http://127.0.0.1:${server.address().port}/${base}/index.html#/command`);await page.waitForTimeout(250);row.command=await snapshot();
 await page.goto(`http://127.0.0.1:${server.address().port}/${base}/index.html#/login`);await page.waitForTimeout(250);row.loginInitial=await snapshot();
 try{await page.locator('input[type=email]').filter({visible:true}).fill('probe@example.test');row.afterInput=await snapshot();await page.getByRole('button',{name:'Sign in',exact:true}).filter({visible:true}).click();await page.waitForTimeout(100);row.afterClick=await snapshot();}catch(e){row.interactionFailure=e.message;}
 const cov=await cdp.send('Profiler.takePreciseCoverage');row.calls=cov.result.filter(x=>x.url.endsWith('jtml-runtime.js')).flatMap(x=>x.functions).filter(f=>['runDirectComponentAction','runDirectComponentFallbackAction','executeClientAction','redirect','applyRoutes','renderDirectComponent','componentBindTargetStatus'].includes(f.functionName)).map(f=>({name:f.functionName,calls:f.ranges[0]?.count}));row.errors=errors;await page.close();
}}finally{await browser.close();await new Promise(r=>server.close(r));fs.writeFileSync('/tmp/jtml-enterprise-login-control-before.json',JSON.stringify(rows,null,2)+'\n');console.log(JSON.stringify(rows,null,2));}})().catch(e=>{console.error(e);process.exitCode=1});

